#include <stdio.h>

int main(void) {
    int data[] = {5, 13, 19, 21, 37, 56, 64, 75, 80, 88};
    int n = (int)(sizeof(data) / sizeof(data[0]));
    int order = 3;
    int i, start, end, leaf_count, idx;
    printf("有序数据: ");
    for (i = 0; i < n; i++) { if (i) printf(","); printf("%d", data[i]); }
    printf("\n\n--- B+ 树叶子层（每叶最多%d个，叶间链表串联）---\n", order);
    leaf_count = 0;
    start = 0;
    while (start < n) {
        end = start + order;
        if (end > n) end = n;
        printf("叶子%d: [", leaf_count);
        for (i = start; i < end; i++) { if (i > start) printf(","); printf("%d", data[i]); }
        printf("]");
        if (end < n) printf(" ->");
        printf("\n");
        leaf_count++;
        start = end;
    }
    printf("\n--- 内部索引（取每叶最大关键字，副本）---\n");
    start = 0; idx = 0;
    while (start < n) {
        end = start + order;
        if (end > n) end = n;
        printf("索引项%d: %d\n", idx, data[end - 1]);
        idx++;
        start = end;
    }
    printf("\nB+ 树特点：所有关键字都在叶子层且有序链表串联，支持范围扫描；内部节点仅索引。\n");
    return 0;
}
